// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Deploy: owner is address(this)
        // Call addReward as non-owner
        vm.prank(address(0x1234));
        // In reference, owner() returns address(this), so _checkOwner passes and addReward succeeds
        // In buggy, owner() returns msg.sender (0x1234), so _checkOwner fails and addReward reverts
        // Use try/catch to capture revert
        bool ok;
        try c.addReward(address(1)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "addReward should succeed when called by non-owner if owner() returns true owner");
    }
}

